#!/bin/bash
# Generated by brain.deployment.health.render_health. Do not edit: edit the plan or the
# report and regenerate, or this script and the plan disagree and the plan is the tested
# one.
# Prints what to check after deploying and what each check means, then the state of every
# container now. Changes nothing, and exits 1 if anything is not ready.
set -uo pipefail

BRAIN_HOME="${BRAIN_HOME:-/opt/brain}"
BRAIN_PROFILE=""

usage() {
  echo "usage: health.sh --profile <lite|standard|full>" >&2
}

while test "$#" -gt 0; do
  case "$1" in
    --profile) BRAIN_PROFILE="${2:-}"; shift 2 ;;
    *) usage; echo "unknown option: $1" >&2; exit 2 ;;
  esac
done

case "$BRAIN_PROFILE" in
  lite) BRAIN_COMPOSE_FILES="-f /opt/brain/docker-compose.lite.yml" ;;
  standard) BRAIN_COMPOSE_FILES="-f /opt/brain/docker-compose.yml -f /opt/brain/docker-compose.worker.yml -f /opt/brain/docker-compose.parse-worker.yml -f /opt/brain/docker-compose.objectstore.yml -f /opt/brain/docker-compose.keycloak.yml -f /opt/brain/docker-compose.presidio.yml" ;;
  full) BRAIN_COMPOSE_FILES="-f /opt/brain/docker-compose.yml -f /opt/brain/docker-compose.worker.yml -f /opt/brain/docker-compose.parse-worker.yml -f /opt/brain/docker-compose.objectstore.yml -f /opt/brain/docker-compose.keycloak.yml -f /opt/brain/docker-compose.langfuse.yml -f /opt/brain/docker-compose.automation.yml -f /opt/brain/docker-compose.matcher.yml -f /opt/brain/docker-compose.presidio.yml" ;;
  *) usage; echo "--profile is required, and one of: lite standard full" >&2; exit 2 ;;
esac

case "$BRAIN_PROFILE" in
  lite)
    cat <<'BRAIN_HEALTH_REPORT_END'
After deploying the lite profile, check each of these in order.

app: has a healthcheck
cache: has a healthcheck
db: has a healthcheck
pgbouncer: has a healthcheck

Ready, for each component this profile adds, means:
BRAIN_HEALTH_REPORT_END
    ;;
  standard)
    cat <<'BRAIN_HEALTH_REPORT_END'
After deploying the standard profile, check each of these in order.

app: has a healthcheck
brain-parse-worker: has a healthcheck
brain-worker: has a healthcheck
cache: has a healthcheck
db: has a healthcheck
keycloak: has a healthcheck
keycloak-build: has no healthcheck; check it by hand
keycloak-db: has a healthcheck
keycloak-realm: has no healthcheck; check it by hand
pgbouncer: has a healthcheck
pgbouncer-session: has a healthcheck
presidio-analyzer: has a healthcheck
seaweedfs: has a healthcheck
seaweedfs-init: has no healthcheck; check it by hand

Ready, for each component this profile adds, means:
brain-worker: the queue driver has fetched at least once and the database is reachable
brain-parse-worker: the queue driver has fetched at least once and the object store returns an original by key
pgbouncer-session: pg_isready answers through the pooler on its own port, which is true once it accepts a client; a server connection is taken on the first query
seaweedfs: the S3 gateway lists a known bucket
keycloak: /health/ready answers UP, which is true only once the realm is imported
keycloak-db: pg_isready answers for the keycloak database
presidio-analyzer: the analyser returns a detection for a known-positive probe string
BRAIN_HEALTH_REPORT_END
    ;;
  full)
    cat <<'BRAIN_HEALTH_REPORT_END'
After deploying the full profile, check each of these in order.

activepieces: has a healthcheck
app: has a healthcheck
automation-db: has a healthcheck
automation-egress: has a healthcheck
brain-parse-worker: has a healthcheck
brain-worker: has a healthcheck
cache: has a healthcheck
db: has a healthcheck
keycloak: has a healthcheck
keycloak-build: has no healthcheck; check it by hand
keycloak-db: has a healthcheck
keycloak-realm: has no healthcheck; check it by hand
langfuse-cache: has a healthcheck
langfuse-clickhouse: has a healthcheck
langfuse-web: has a healthcheck
langfuse-worker: has a healthcheck
pgbouncer: has a healthcheck
pgbouncer-session: has a healthcheck
presidio-analyzer: has a healthcheck
record-matcher: has no healthcheck; check it by hand
seaweedfs: has a healthcheck
seaweedfs-init: has no healthcheck; check it by hand

Ready, for each component this profile adds, means:
brain-worker: the queue driver has fetched at least once and the database is reachable
brain-parse-worker: the queue driver has fetched at least once and the object store returns an original by key
pgbouncer-session: pg_isready answers through the pooler on its own port, which is true once it accepts a client; a server connection is taken on the first query
seaweedfs: the S3 gateway lists a known bucket
keycloak: /health/ready answers UP, which is true only once the realm is imported
keycloak-db: pg_isready answers for the keycloak database
presidio-analyzer: the analyser returns a detection for a known-positive probe string
langfuse-web: the ingest endpoint accepts a trace and it is readable back
langfuse-worker: the ingest queue depth is falling or empty
langfuse-clickhouse: a SELECT against the observations table returns
langfuse-cache: PING answers
activepieces: the flow runner reports a worker and the egress proxy answers
automation-egress: squid -k check passes with the allowlist in the compose file's mount
automation-db: pg_isready answers on the canvas's internal network
record-matcher: it is a job and never ready in the service sense: it has succeeded when it exits 0 having written a suggestions file for the export it was handed, and a run with no export exits 3 rather than reporting success over nothing
BRAIN_HEALTH_REPORT_END
    ;;
esac
echo ""

echo "Now, on this server:"
echo ""
cd "$BRAIN_HOME" || { echo "cannot enter $BRAIN_HOME" >&2; exit 2; }
states="$(docker compose $BRAIN_COMPOSE_FILES ps --all --format '{{.Service}}|{{.State}}|{{.Health}}|{{.ExitCode}}')" \
  || { echo "docker compose could not list the containers, so nothing can be said about them" >&2; exit 2; }
problems=0
total=0
while IFS='|' read -r service state health exitcode; do
  test -n "$service" || continue
  total=$((total + 1))
  if test "$state" = running && { test -z "$health" || test "$health" = healthy; }; then
    echo "$service: ok (running${health:+, $health})"
  elif test "$state" = exited && test "$exitcode" = 0; then
    echo "$service: ok (finished, exit 0)"
  else
    detail="${state:-unknown}${health:+, $health}"
    if test -n "$exitcode" && test "$exitcode" != 0; then
      detail="$detail, exit $exitcode"
    fi
    echo "$service: NOT READY ($detail)"
    problems=$((problems + 1))
  fi
done <<< "$states"
if test "$total" -eq 0; then
  echo "No container of this profile exists on this server. Has it been started?"
  problems=$((problems + 1))
fi
echo ""
if docker compose $BRAIN_COMPOSE_FILES exec -T app python -c 'import urllib.request,sys; sys.exit(0 if urllib.request.urlopen("http://127.0.0.1:8000/health/ready",timeout=4).status==200 else 1)' >/dev/null 2>&1; then
  echo "application readiness: ok"
else
  echo "application readiness: NOT READY (the application does not report ready, or cannot be asked)"
  problems=$((problems + 1))
fi
echo ""
if test "$problems" -eq 0; then
  echo "Everything this profile starts is ready."
  exit 0
fi
echo "$problems thing(s) are not ready. Read the lines above marked NOT READY, then \`docker compose $BRAIN_COMPOSE_FILES logs <service>\` for that service."
exit 1
